"use client";

import { useState } from 'react';
import { geminiService } from '@/services/ai/gemini-service';
import { Roadmap } from '@/types/sdg';
import { 
  Zap, 
  Search, 
  Loader2, 
  CheckCircle2, 
  Globe, 
  LayoutDashboard,
  Users,
  Settings,
  ChevronRight,
  Sparkles
} from 'lucide-react';
import { ClassroomRadar } from '@/components/teacher/ClassroomRadar';
import { useSDGStore } from '@/services/storage/sdg-store';

export default function TeacherDashboard() {
  const [courseTitle, setCourseTitle] = useState('');
  const [loading, setLoading] = useState(false);
  const { currentRoadmap, setRoadmap } = useSDGStore();

  const handleArchitect = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!courseTitle.trim()) return;
    
    setLoading(true);
    try {
      const result = await geminiService.generateRoadmap(courseTitle);
      setRoadmap(result);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const roadmap = currentRoadmap;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans selection:bg-emerald-500/30">
      {/* Navbar */}
      <nav className="h-20 border-b border-white/5 bg-slate-950/50 backdrop-blur-xl flex items-center justify-between px-8 sticky top-0 z-50">
        <div className="flex items-center space-x-4">
          <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-500/20">
            <Globe className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-sm font-black uppercase tracking-tighter italic">Sustain-Ability AI</h1>
            <p className="text-[10px] font-bold uppercase text-emerald-500 tracking-widest">Teacher Architect</p>
          </div>
        </div>
        
        <div className="flex items-center space-x-8">
          <button className="text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-white transition-colors">Documentation</button>
          <div className="w-10 h-10 rounded-full bg-slate-900 border border-white/5 flex items-center justify-center text-[10px] font-black">SA</div>
        </div>
      </nav>

      <div className="flex">
        {/* Sidebar */}
        <aside className="w-20 lg:w-64 h-[calc(100vh-80px)] border-r border-white/5 bg-slate-950/30 p-4 space-y-4">
          <button className="w-full h-12 rounded-2xl bg-emerald-600/10 text-emerald-500 flex items-center justify-center lg:justify-start lg:px-4 space-x-3 transition-all hover:bg-emerald-600/20">
            <LayoutDashboard className="w-5 h-5 shrink-0" />
            <span className="hidden lg:block text-xs font-black uppercase tracking-widest italic">Dashboard</span>
          </button>
          <button className="w-full h-12 rounded-2xl bg-slate-900/50 text-slate-500 flex items-center justify-center lg:justify-start lg:px-4 space-x-3 transition-all hover:bg-white/5 hover:text-slate-300">
            <Users className="w-5 h-5 shrink-0" />
            <span className="hidden lg:block text-xs font-black uppercase tracking-widest italic">Classroom</span>
          </button>
          <button className="w-full h-12 rounded-2xl bg-slate-900/50 text-slate-500 flex items-center justify-center lg:justify-start lg:px-4 space-x-3 transition-all hover:bg-white/5 hover:text-slate-300">
            <Settings className="w-5 h-5 shrink-0" />
            <span className="hidden lg:block text-xs font-black uppercase tracking-widest italic">Settings</span>
          </button>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-8 lg:p-16 overflow-y-auto">
          <div className="max-w-4xl mx-auto space-y-16">
            
            {/* Header Section */}
            <header className="space-y-6">
              <div className="flex items-center space-x-3 text-[10px] font-black uppercase tracking-[0.3em] text-emerald-500">
                <Sparkles className="w-4 h-4" />
                <span>SDG Educational Architect</span>
              </div>
              <h2 className="text-5xl lg:text-7xl font-black tracking-tighter uppercase italic leading-[0.85] text-white">
                Design <br /> Sustainable <br /> Futures
              </h2>
            </header>

            {/* Input Form */}
            <section className="relative group">
              <div className="absolute -inset-1 bg-gradient-to-r from-emerald-600 to-teal-600 rounded-[3rem] blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
              <form onSubmit={handleArchitect} className="relative bg-slate-900 border border-white/5 p-4 rounded-[2.5rem] flex items-center">
                <div className="w-14 h-14 rounded-2xl bg-slate-950 flex items-center justify-center text-slate-500 shrink-0">
                  <Search className="w-6 h-6" />
                </div>
                <input 
                  type="text" 
                  value={courseTitle}
                  onChange={(e) => setCourseTitle(e.target.value)}
                  placeholder="Type a course title (e.g., Biology, Python)..."
                  className="bg-transparent border-none focus:ring-0 flex-1 px-8 text-lg font-bold placeholder:text-slate-800 text-slate-100"
                />
                <button 
                  disabled={loading}
                  className="h-14 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-800 text-white rounded-2xl px-10 font-black text-[10px] uppercase tracking-widest transition-all flex items-center space-x-3 shadow-xl shadow-emerald-500/20"
                >
                  {loading ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin text-white" />
                      <span>Architecting...</span>
                    </>
                  ) : (
                    <>
                      <Zap className="w-4 h-4" />
                      <span>Generate Roadmap</span>
                    </>
                  )}
                </button>
              </form>
            </section>

            {/* Side by Side Mapping & Radar */}
            {roadmap && !loading && (
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-5 duration-1000">
                <div className="space-y-8">
                  <div className="p-10 bg-emerald-600/5 border border-emerald-500/10 rounded-[3rem] space-y-6 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-12 opacity-5 translate-x-8 -translate-y-8 group-hover:scale-110 transition-transform duration-1000">
                      <Globe className="w-48 h-48 text-emerald-500" />
                    </div>
                    
                    <div className="space-y-2 relative">
                      <span className="text-[10px] font-black uppercase tracking-widest text-emerald-500">Primary Impact Goal</span>
                      <h3 className="text-4xl font-black uppercase italic tracking-tighter text-white">SDG {roadmap.primarySDG.id}: {roadmap.primarySDG.name}</h3>
                      <p className="text-sm text-slate-400 font-medium max-w-xl leading-relaxed">{roadmap.primarySDG.description}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 gap-6">
                    {roadmap.modules.map((mod, idx) => (
                      <div key={mod.id} className="p-8 bg-slate-900/50 border border-white/5 rounded-[2.5rem] space-y-6 hover:border-emerald-500/20 transition-all flex flex-col justify-between">
                        <div className="space-y-4">
                          <div className="flex items-center justify-between">
                            <span className="text-[9px] font-black uppercase tracking-widest text-emerald-500">Module 0{idx + 1}</span>
                            <div className="w-8 h-8 rounded-xl bg-slate-950 flex items-center justify-center">
                              <ChevronRight className="w-4 h-4 text-slate-700" />
                            </div>
                          </div>
                          <h4 className="text-lg font-black uppercase italic tracking-tighter text-slate-100 leading-none">{mod.title}</h4>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{mod.description}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>

                <div className="space-y-8">
                   <ClassroomRadar />
                   
                   <div className="p-8 bg-slate-900 rounded-[2.5rem] border border-white/5 space-y-6">
                      <h4 className="text-xs font-black uppercase tracking-widest italic text-slate-500">Live Feedback Stream</h4>
                      <div className="space-y-3">
                         <div className="text-[10px] p-3 bg-slate-950 rounded-xl border border-white/5 font-mono text-emerald-500/70">
                            [System] Course &quot;{roadmap.courseTitle}&quot; mapped to SDG {roadmap.primarySDG.id}
                         </div>
                         <div className="text-[10px] p-3 bg-slate-950 rounded-xl border border-white/5 font-mono text-slate-500">
                            [Auth] Teacher session initialized...
                         </div>
                      </div>
                   </div>
                </div>
              </div>
            )}

            {!roadmap && !loading && (
              <div className="py-24 flex flex-col items-center space-y-6 opacity-30">
                <div className="w-20 h-20 bg-slate-900 rounded-[2rem] flex items-center justify-center text-slate-700">
                  <LayoutDashboard className="w-8 h-8" />
                </div>
                <div className="text-center space-y-2">
                   <h3 className="text-xl font-black uppercase italic tracking-tighter">Ready for Architecture</h3>
                   <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-700">Enter a course title to manifest an SDG sequence</p>
                </div>
              </div>
            )}

          </div>
        </main>
      </div>
    </div>
  );
}
